import{_ as t,d as o,e as a,x as r}from"./chunks/framework.BRr8VP3a.js";const b=JSON.parse('{"title":"A.9 HV09 Structural Load (Full Interface Card)","description":"","frontmatter":{"title":"A.9 HV09 Structural Load (Full Interface Card)","xkChars":0,"xkWords":1535},"headers":[],"relativePath":"en/theory/appendix-a/a-09.md","filePath":"en/theory/appendix-a/a-09.md"}'),i={name:"en/theory/appendix-a/a-09.md"};function n(d,e,s,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<div class="theory-source"><h1 id="section-a-9" tabindex="-1"><span class="xk-num"><span class="xk-num__n">A.9</span><span class="xk-num__gap"></span></span>HV09 Structural Load (Full Interface Card) <a class="header-anchor" href="#section-a-9" aria-label="Permalink to &quot;A.9 HV09 Structural Load (Full Interface Card) {#section-a-9}&quot;">​</a></h1><p>A. Identity, Proposition, and Scope</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Interface ID (<code>id</code>)</td><td>HV09</td></tr><tr><td>Qualified ID (<code>qualified_id</code>)</td><td><code>human_variable:HV09</code></td></tr><tr><td>Name (<code>name</code>)</td><td>Structural Load</td></tr><tr><td>Claim type (<code>claim_type</code>)</td><td>H</td></tr><tr><td>Contract role (<code>contract_role</code>)</td><td><code>human_variable_interface</code></td></tr><tr><td>Proposition (<code>proposition</code>)</td><td>Structural load in human structures must be recorded together with tasks, coordination losses, maintenance requirements, capacity, recovery margins, and positions bearing costs.</td></tr><tr><td>Scope (<code>scope</code>)</td><td>Human structures under conditions of continuing operation, maintenance, care, or high pressure</td></tr><tr><td>Conditions for suspension (<code>pause_condition</code>)</td><td>Metaphors of entropy, fragility, or resilience are used without identifying tasks, capacity, and mechanisms of recovery</td></tr></tbody></table></div><p>B. Formal Dependencies and Limits on Conclusions</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Inferential dependencies (<code>inferential_requires</code>)</td><td>None (empty set)</td></tr><tr><td>Protocol dependencies (<code>protocol_requires</code>)</td><td>1. EVIDENCE<br>2. SOURCE</td></tr><tr><td>Qualification/specialization (<code>specializes</code>)</td><td>None (empty set)</td></tr><tr><td>References to applicable objects (<code>applies_to</code>)</td><td>None (empty set)</td></tr><tr><td>Conditional support routes (<code>conditional_support_routes</code>)</td><td>1. route_id=HV09-R0-instant-task-capacity;<br>claim_level=descriptive_classification;<br>when=Tasks or coordination requirements, capacity, recovery margins, and their distributions are observable under the same window, position, and type mapping;<br>additional_inferential_requires=None (empty set);<br>additional_protocol_requires=None (empty set);<br>allowed_conclusion=Register the instantaneous task–capacity relation, margins, backlogs, local gaps, and recovery status;<br>result_ceiling=Description within the same window only. An instantaneous peak or gap does not automatically establish an overload mechanism, cumulative damage, or collapse.<br>2. route_id=HV09-R1-overload-mechanism;<br>claim_level=mechanism_explanation;<br>when=All conditions for applying CM-LOAD are met, and an eligible G2-instance shows an above-threshold effect of a channel for load, replenishment, load reduction, or recovery on the preselected outcome;<br>additional_inferential_requires=G2-instance, CM-LOAD;<br>additional_protocol_requires=CAUSAL, E4;<br>allowed_conclusion=Register a candidate overload or recovery mechanism within the specified position, type, window, and channel;<br>result_ceiling=Do not generalize the result as entropy or resilience, or infer inevitable collapse at every position. It does not directly generate an obligation to reduce load or make sacrifices.<br>3. route_id=HV09-R2-cumulative-overload;<br>claim_level=intertemporal_explanation;<br>when=The overload mechanism already has support from a G2-instance and CM-LOAD, and a G3-instance shows that historical load provides a conditional increment for subsequent capacity, errors, or recovery;<br>additional_inferential_requires=G2-instance, CM-LOAD, G3-instance;<br>additional_protocol_requires=CAUSAL, E4;<br>allowed_conclusion=Register a candidate for cumulative damage or delayed recovery with a historical increment beyond the current state, limited to the pre-registered carrier, window, and outcome;<br>result_ceiling=Do not infer irreversibility, inevitable collapse, attribution of responsibility, or a duty for a named subject to bear the load.<br>4. route_id=HV09-R3-carried-cumulative-overload;<br>claim_level=intertemporal_explanation;<br>when=All conditions of CM-LOAD-carried-cumulative are met. An eligible G2-instance covers the specified channel of load, replenishment, or recovery and the stated cross-window outcome. Verify the carrier of current damage or capacity, accumulation or recovery across windows, and discriminating causal materials under §4.5;<br>additional_inferential_requires=G2-instance, CM-LOAD;<br>additional_protocol_requires=CAUSAL, E4;<br>allowed_conclusion=Register a candidate for cumulative damage or delayed recovery through carrier transmission within the specified carrier, window, and outcome;<br>result_ceiling=Do not register a G3 historical increment or infer a damage mechanism from one overload event or a persistent correlation. Do not infer irreversibility, inevitable collapse, responsibility, or a duty to make sacrifices.</td></tr><tr><td>Permitted inferences (<code>allowed_inference</code>)</td><td>1. Candidate overload, insufficient margins, maintenance gaps, and differences in recovery</td></tr><tr><td>Prohibited leaps (<code>prohibited_leap</code>)</td><td>1. Assuming people taking up the work should continue to bear it<br>2. Treating high load as proof of devotion<br>3. Equating a subject under overload with a mechanism of destabilization</td></tr></tbody></table></div><p>C. Nine-Axis Scale and Object Contract</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Nine-axis scale profile (<code>scale_profile</code>)</td><td>SP=&lt;A,X,T,O,C,R,I,N,J&gt;. A=Aggregation level covers individual task loads, cases of uptake, populations of positions or groups, distributions of load and capacity, and aggregation rules. X=Spatial extent covers sites of work or care, organizational boundaries, digital workspaces, and the extent of outsourcing across domains. T=Time span covers instantaneous peaks, persistent backlogs, recovery lags, and windows across periods and generations. O=Organizational level covers uptake roles, teams, organizations, institutions, and governance ecologies. C=Causal level covers task events, mechanisms of interaction between tasks and capacity, meso-level bottleneck structures, institutional allocation, and systemic conditions. R=Resolution covers original task and working-hour records, load sequences, cases of uptake, capacity distributions, delay and error metrics, and summaries. Record compression loss as well. I=Scope of influence covers people directly taking up the work, people dependent on services, indirect substitutes, second-order spillovers, and costs across domains and generations. N=Network topology scope covers task dependencies, key bottlenecks, substitute nodes, recovery paths, and outsourcing networks across domains. J=Scope of jurisdiction and authorization requires separate authorization records for task assignment, resource adjustments, stopping, use of performance evaluations, and remedy. Preserve the distributions of load and capacity</td></tr><tr><td>Effective object (<code>effective_object</code>)</td><td>The structural relation of tasks and coordination requirements to available capacity and recovery margins within a given window</td></tr><tr><td>Scale invariants (<code>scale_invariants</code>)</td><td>1. Load, capacity, recovery, and positions bearing costs</td></tr><tr><td>Required additions for scale elevation (<code>required_scale_additions</code>)</td><td>1. Load distribution<br>2. Masking by aggregation<br>3. Carryover of responsibility<br>4. Intergenerational impacts</td></tr><tr><td>What changes with scale (<code>changing_semantics</code>)</td><td>1. Bottlenecks, capacity, and ways of recovering can change with the level</td></tr><tr><td>Inapplicable objects (<code>non_applicable_objects</code>)</td><td>1. Processes without sustained disequilibrium, maintenance requirements, or human uptake requirements</td></tr><tr><td>Prohibited elevations (<code>forbidden_elevation</code>)</td><td>1. Letting average load mask local overload</td></tr></tbody></table></div><p>D. State, Evidence, and Variable Flows</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>State set (<code>state</code>)</td><td>1. Low load<br>2. Bearable<br>3. Critical<br>4. Overloaded<br>5. Recovering</td></tr><tr><td>Observables (<code>observables</code>)</td><td>1. Task volume per unit of time, backlog, delays, and error rate<br>2. Capacity of personnel and resources, hidden labor, and availability of substitutes<br>3. Stopping, absence, exit, and recovery curves<br>4. Differences between average load and its distribution at key local uptake positions</td></tr><tr><td>Evidence requirements (<code>evidence</code>)</td><td>1. Task volume<br>2. Delays and errors<br>3. Personnel and resources<br>4. Recovery records<br>5. Exit and absence<br>6. For the stated objective, distinguish execution, simultaneous activities, management, being on call, and opportunity costs. Specify overlaps, units, and transfers across positions. Do not sum them directly as a single burden<br>7. When the task in question depends on continuous blocks of time, also record how responsibilities as the default contact, being on call, and filling in at short notice cut into the usable whole blocks. Do not convert this into hours</td></tr><tr><td>Input dependencies and interface content (<code>input_dependencies</code>)</td><td>1. Uptake layer<br>2. Drive–uptake chain<br>3. Conditional potential field<br>4. R0 registers task volume, capacity, backlog, and recovery for the same type, time window, and position bearing the load. It does not require G2 as a premise for description.<br>5. R1 uses G2 and CM-LOAD for channel effects. R3 checks the current state, its formation, and effects across windows under §4.5 for accumulation through carriers. R2 tests the additional historical conditional increment separately under G3. H5 traces cannot substitute for evidence of later effects or testing under G3.<br>6. Lack of formal mechanism support for a route does not cancel findings of general harm, continuing burdens, or historical causation already supported by independent domain evidence. Register conclusions separately according to their own grounds.</td></tr><tr><td>Output effects and variable flows (<code>output_effects</code>)</td><td>1. State updates<br>2. Behavior of destabilization<br>3. Maintenance and repair needs</td></tr><tr><td>Time window and lag (<code>time_window_and_lag</code>)</td><td>Distinguish instantaneous peaks, persistent backlogs, recovery lags, and intergenerational costs</td></tr><tr><td>Uncertainty (<code>uncertainty</code>)</td><td>Record hidden labor, outsourced costs, and absence for reasons of protection</td></tr><tr><td>Local exclusion zone (<code>local_exclusion_zone</code>)</td><td>Informal labor, family care, outsourcing, and uptake positions with low visibility</td></tr><tr><td>Affected positions (<code>affected_positions</code>)</td><td>1. People taking up the work<br>2. People dependent on services<br>3. People taking over<br>4. Positions to which costs spill over</td></tr></tbody></table></div><p>E. Uptake, Responsibility, Normative Status, Ceilings, and Correction</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Uptake carriers (<code>carrier</code>)</td><td>1. Personnel<br>2. Positions<br>3. Procedures<br>4. Facilities<br>5. Budgets</td></tr><tr><td>Responsible parties (<code>responsible_subject</code>)</td><td>1. Task assigners<br>2. Resource allocators<br>3. Parties granting authorization<br>4. Parties responsible for oversight<br>5. Parties responsible for remedy</td></tr><tr><td>Normative status (<code>normative_status</code>)</td><td>High efficiency or the ability to carry a heavy load does not establish normative justification</td></tr><tr><td>Judgment ceiling (<code>judgment_ceiling</code>)</td><td>R0 describes tasks, capacity, and recovery within the same window. R1 uses G2 and CM-LOAD to explain a specified channel within stated limits. R3 uses §4.5 to judge cumulative damage or delayed recovery through transmission by a current carrier. R2 judges historical increments beyond the current representation only with additional G3. Persistent correlation, a temporary overload, or an overall average cannot substitute for the corresponding evidence.</td></tr><tr><td>Action ceiling (<code>action_ceiling</code>)</td><td>This variable produces only descriptions of load, capacity, recovery, local overload, and needs to reduce load or add resources. It does not authorize task reduction, resource commitments, personnel action based on performance, or compelling people to bear the load. Any real-world adjustment separately requires C12, explicit N premises at runtime, J authorization, and O procedures</td></tr><tr><td>Counterexamples (<code>counterexamples</code>)</td><td>1. Average capacity overall is adequate, but some key uptake positions remain overloaded<br>2. Metaphors of entropy or resilience alone fail to identify tasks, capacity, or recovery channels</td></tr><tr><td>Appeal (<code>appeal</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, people taking up work can report hidden labor, overload, and recovery needs through a safe, accessible channel with anti-retaliation protection. This triggers review independent of the original judgment about load or the chain of performance or task decisions</td></tr><tr><td>Rollback (<code>rollback</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, once rollback is authorized, the designated responsible party must within the stated deadline revoke erroneous load judgments and their effects on performance or responsibility and actually restore task, resource, and record states. Preserve versions and verification of completion</td></tr></tbody></table></div></div>',1)])])}const h=t(i,[["render",n]]);export{b as __pageData,h as default};
